// Tests for the camera rules, without a camera: the body points are written by hand.
// Run: npm test (Node 18+). Code generated by Claude (Anthropic), an AI system.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { RULES, POINT, chestBox, handOnChest, eyesClosed, stillness, holdTimer } from '../src/camera-rules.js';

// A person facing the camera: shoulders at y 0.4, hips at y 0.9, hands down by the hips.
function body(overrides = {}) {
  const pts = Array.from({ length: 33 }, () => ({ x: 0.5, y: 0.95, visibility: 0.1 }));
  const set = (i, x, y) => { pts[i] = { x, y, visibility: 0.9 }; };
  set(POINT.nose, 0.5, 0.25);
  set(POINT.lShoulder, 0.65, 0.4);
  set(POINT.rShoulder, 0.35, 0.4);
  set(POINT.lHip, 0.6, 0.9);
  set(POINT.rHip, 0.4, 0.9);
  set(POINT.lWrist, 0.7, 0.88);
  set(POINT.rWrist, 0.3, 0.88);
  for (const [i, [x, y]] of Object.entries(overrides)) set(Number(i), x, y);
  return pts;
}

test('chest area: between the shoulders, from the shoulder line down the upper part of the torso', () => {
  const box = chestBox(body());
  assert.ok(box.x0 < 0.35 && box.x1 > 0.65);
  assert.ok(box.y0 < 0.4 && box.y1 > 0.6 && box.y1 < 0.9);
});

test('a hand on the chest is seen; hands down by the hips are not', () => {
  assert.equal(handOnChest(body()), false);
  assert.equal(handOnChest(body({ [POINT.rWrist]: [0.45, 0.5] })), true);
});

test('no shoulders in the picture: no chest area, nothing is claimed', () => {
  const pts = body();
  pts[POINT.lShoulder] = { x: 0.65, y: 0.4, visibility: 0.1 };
  assert.equal(chestBox(pts), null);
  assert.equal(handOnChest(pts), false);
  assert.equal(handOnChest(undefined), false);
});

test('only the upper body in the picture (laptop camera): the chest area is still found', () => {
  const pts = body({ [POINT.lWrist]: [0.5, 0.55] });
  pts[POINT.lHip] = { x: 0.6, y: 1.2, visibility: 0.05 };
  pts[POINT.rHip] = { x: 0.4, y: 1.2, visibility: 0.05 };
  assert.ok(chestBox(pts));
  assert.equal(handOnChest(pts), true);
});

test('eyes closed only when the face model is sure about both eyes', () => {
  const shapes = (l, r) => [{ categoryName: 'eyeBlinkLeft', score: l }, { categoryName: 'eyeBlinkRight', score: r }];
  assert.equal(eyesClosed(shapes(0.9, 0.8)), true);
  assert.equal(eyesClosed(shapes(0.9, 0.2)), false);
  assert.equal(eyesClosed(null), false);
});

test('the timer fires once after the hold time, and again only after the condition was off for a while', () => {
  const timer = holdTimer(1.5, 3);
  assert.equal(timer.update(true, 0).fire, false);
  assert.equal(timer.update(true, 1000).fire, false);
  assert.equal(timer.update(true, 1600).fire, true);
  assert.equal(timer.update(true, 5000).fire, false); // still holding: no flood of events
  timer.update(false, 6000);
  timer.update(true, 7000); // off for only one second: not re-armed
  assert.equal(timer.update(true, 9000).fire, false);
  timer.update(false, 10000);
  timer.update(false, 13500); // off long enough: re-armed
  timer.update(true, 14000);
  assert.equal(timer.update(true, 15600).fire, true);
});

test('stillness: a nose that stays put counts as still, one that moves does not', () => {
  const calm = stillness(2, 0.03);
  let last = false;
  for (let t = 0; t <= 2000; t += 100) last = calm.update({ x: 0.5 + (t % 200 ? 0.002 : 0), y: 0.3 }, t);
  assert.equal(last, true);
  const busy = stillness(2, 0.03);
  for (let t = 0; t <= 2000; t += 100) last = busy.update({ x: 0.4 + t / 20000, y: 0.3 }, t);
  assert.equal(last, false);
});

test('the rules use the thresholds shown on the page', () => {
  assert.equal(RULES.chestSeconds, 1.5);
  assert.equal(RULES.sleepSeconds, 5);
});

// The team's confirmation layer: the machine raises the alarm only without confirmation.
import { createMachine, STATUS, DEST } from '../src/engine.js';
import { CELLS, CREW } from '../src/config.js';

test('after "Are you okay?": "okay" gives no alarm; "need help" and no answer call the doctor', () => {
  const machine = createMachine({ cells: CELLS, crew: CREW, state: { aiWorks: true, doctorOnBoard: false, linkToEarth: true } });
  const cam = (value) => machine.receive({ person: 'crew-1', source: 'camera', indicator: 'camera', value });
  const ok = cam('chest_grab_ok');
  assert.equal(ok.status, STATUS.IGNORED);
  assert.equal(ok.dest, DEST.NONE);
  for (const value of ['chest_grab_help', 'chest_grab_no_answer']) {
    const e = cam(value);
    assert.equal(e.status, STATUS.OUT, value);
    assert.equal(e.dest, DEST.DOCTOR_EARTH, value);
    assert.ok(e.steps.every((s) => s.by !== 'ai'), value);
  }
});
